// Real Supabase integration; no network or provider calls until configured.
(async()=>{
 const config=await fetch('auth-config.json').then(r=>r.json()).catch(()=>null);
 if(!config?.supabaseUrl||!config?.publishableKey)return;
 let createClient;
 try{({createClient}=await import('https://esm.sh/@supabase/supabase-js@2'));}catch{$('#auth-status').textContent='Could not load sign-in. Your local books are still available.';return;}
 const client=createClient(config.supabaseUrl,config.publishableKey,{auth:{flowType:'pkce'}});
 let user=null,revision=null,dirty=false,busy=false,paused=false,timer,authUserId=null;
 const status=t=>{$('#cloud-status').textContent=t;$('#auth-status').textContent=t};
 const guest=()=>({books:JSON.parse(localStorage.getItem('wd-books')||'[]'),memories:JSON.parse(localStorage.getItem('wd-memories')||'[]')});
 function authUI(){const root=$('#auth-options');root.replaceChildren();if(user){$('#account').textContent='My account ↗';$('#auth-description').textContent='Signed in as '+user.email;const importButton=document.createElement('button');importButton.className='primary';importButton.textContent='Import books from this browser';importButton.onclick=()=>{const local=guest(),snapshot=window.libraryBridge.get();const existing=new Set(snapshot.books.map(b=>b.id));snapshot.books.push(...local.books.filter(b=>!existing.has(b.id)));window.libraryBridge.set(snapshot);window.cloudQueue();toast('Local books added to your account library.');};const logout=document.createElement('button');logout.className='backup-button';logout.textContent='Sign out';logout.onclick=async()=>{await flush();if(dirty||busy){toast('Cloud save is pending. Download a backup before signing out.');return}const {error}=await client.auth.signOut();if(error)toast(error.message)};root.append(importButton,logout)}else{$('#account').textContent='Sign in ↗';$('#auth-description').textContent='Sign in to save your books to your account and open them on another device.';const google=document.createElement('button');google.className='primary';google.textContent='Continue with Google';google.onclick=async()=>{const {error}=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/'}});if(error)status(error.message)};const form=document.createElement('form');form.innerHTML='<label>Email address<input type="email" required autocomplete="email" placeholder="you@example.com"></label><button class="primary">Email me a sign-in link</button>';form.onsubmit=async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;const {error}=await client.auth.signInWithOtp({email:form.querySelector('input').value.trim(),options:{emailRedirectTo:location.origin+'/'}});status(error?error.message:'Check your email for your sign-in link.');btn.disabled=false};root.append(google,form)}}
 async function flush(){clearTimeout(timer);if(!user||!dirty||busy||paused)return;busy=true;dirty=false;status('Saving to your account…');const owner=user.id;const payload=window.libraryBridge.get();let result;try{const next=(revision||0)+1;const data={user_id:owner,payload,revision:next,updated_at:new Date().toISOString()};result=revision===null?await client.from('diary_libraries').insert(data).select('revision').single():await client.from('diary_libraries').update(data).eq('user_id',owner).eq('revision',revision).select('revision').maybeSingle();if(result.error||!result.data){dirty=true;paused=true;status('Cloud sync paused. Keep a backup; reload to check for newer edits.');}else{revision=result.data.revision;status('Saved to your account ✓')}}catch{dirty=true;status('Offline · changes kept on this browser');}finally{busy=false;if(dirty&&!paused)timer=setTimeout(flush,4000)}}
 window.cloudQueue=()=>{if(!user)return;dirty=true;status('Changes saved locally · syncing…');clearTimeout(timer);timer=setTimeout(flush,900)};
 async function useSession(session){const id=session?.user?.id||null;if(id===authUserId){user=session?.user||null;authUI();return}authUserId=id;user=session?.user||null;revision=null;paused=false;dirty=false;clearTimeout(timer);document.querySelector('main').inert=true;try{if(user){const {data,error}=await client.from('diary_libraries').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error){paused=true;status('Could not load account books. Local books are unchanged.');return}window.libraryScope=user.id;revision=data?.revision??null;const cached=JSON.parse(localStorage.getItem('wd-account-'+user.id+'-wd-books')||'null');const localNewer=data?.payload&&cached?.some(b=>{const remote=data.payload.books?.find(r=>r.id===b.id);return !remote||Date.parse(b.updated)>Date.parse(remote.updated)});if(localNewer){paused=true;dirty=true;window.libraryBridge.set({books:cached,memories:JSON.parse(localStorage.getItem('wd-account-'+user.id+'-wd-memories')||'[]')});status('Unsynced local changes found. Download a backup before resolving cloud differences.')}else{window.libraryBridge.set(data?.payload||(cached?{books:cached,memories:[]}:null));status(data?'Account books loaded ✓':'Account ready · create a book or import local books.')}}else{window.libraryScope=null;window.libraryBridge.set(guest());status('Stored on this browser · sign in for account sync')}}catch{status('Could not load account books. Your local copies are unchanged.')}finally{document.querySelector('main').inert=false;authUI()}}
 client.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>useSession(session),0)});
 authUI();const {data}=await client.auth.getSession();await useSession(data.session);
 window.addEventListener('online',()=>{if(dirty)flush()});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
})();


